<div class="modulo-cabecalho"><div><h1><i class="fa-solid fa-table-columns"></i> Mapear colunas</h1><p>Associe os cabeçalhos da planilha aos campos do MonanaFinancial. Os campos com <b>*</b> são obrigatórios.</p></div><a class="btn btn-outline" href="<?php echo URL_BASE; ?>/importacao/index">Cancelar</a></div>
<form method="post" action="<?php echo URL_BASE; ?>/importacao/processar"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrf_token); ?>"><div class="mapa-layout"><section class="cartao-mapa"><h2>Associação de campos</h2><div class="mapa-campos"><?php foreach(['data_transacao'=>'Data *','valor'=>'Valor *','tipo'=>'Tipo *','filial_id'=>'Filial (ID) *','categoria_id'=>'Categoria (ID) *','descricao'=>'Descrição','metodo_pagamento'=>'Método de pagamento'] as $campo=>$rotulo): ?><label><span><?php echo $rotulo; ?></span><select name="mapa[<?php echo $campo; ?>]"><option value="">Não importar</option><?php foreach($cabecalhos as $i=>$h): ?><option value="<?php echo $i; ?>"><?php echo htmlspecialchars($h ?: 'Coluna '.($i+1)); ?></option><?php endforeach; ?></select></label><?php endforeach; ?></div><button class="btn btn-primary" type="submit"><i class="fa-solid fa-check"></i> Validar e importar</button></section><aside class="cartao-preview"><h2>Pré-visualização</h2><div class="preview-scroll"><table><thead><tr><?php foreach($cabecalhos as $h): ?><th><?php echo htmlspecialchars($h); ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($preview as $linha): ?><tr><?php foreach($linha as $valor): ?><td><?php echo htmlspecialchars((string)$valor); ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></aside></div></form><style>.mapa-layout{display:grid;grid-template-columns:minmax(300px,1fr) minmax(0,1.4fr);gap:20px}.cartao-mapa,.cartao-preview{background:var(--white);border:1px solid var(--border);border-radius:14px;padding:22px}.cartao-mapa h2,.cartao-preview h2{font-size:17px;margin:0 0 16px;color:var(--navy-deep)}.mapa-campos{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-bottom:22px}.mapa-campos label{display:grid;gap:6px;font-size:13px;font-weight:700}.mapa-campos select{padding:9px;border:1px solid var(--border);border-radius:7px;background:#fff}.preview-scroll{overflow:auto}.preview-scroll table{border-collapse:collapse;width:100%;font-size:12px}.preview-scroll th{background:var(--navy-deep);color:#fff}.preview-scroll th,.preview-scroll td{padding:9px;border:1px solid var(--border);text-align:left;white-space:nowrap}.preview-scroll tbody tr:nth-child(even){background:var(--bg)}.mapa-campos label span b{color:var(--red)}@media(max-width:900px){.mapa-layout{grid-template-columns:1fr}.mapa-campos{grid-template-columns:1fr}}</style>
